<style>
.ma{--b:#e3e8ef;--m:#667085;--t:#182230;--p:#377dff}.ma .ma-head{display:flex;align-items:flex-end;justify-content:space-between;gap:12px;margin-bottom:12px}.ma .breadcrumb{margin:0 0 4px;font-size:11px}.ma h1{margin:0;color:var(--t);font-size:22px;font-weight:750}.ma .subtitle{margin-top:3px;color:var(--m);font-size:11.5px}.ma .panel{border:1px solid var(--b);border-radius:8px;background:#fff;box-shadow:0 3px 12px rgba(16,24,40,.035);overflow:hidden}.ma .panel-head{display:flex;align-items:center;justify-content:space-between;padding:11px 13px;border-bottom:1px solid #edf0f4}.ma .panel-head h2{margin:0;color:#344054;font-size:12.5px;font-weight:750}.ma .panel-body{padding:13px}.ma .kpis{display:grid;grid-template-columns:repeat(6,1fr);margin-bottom:12px;border:1px solid var(--b);border-radius:8px;background:#fff;overflow:hidden}.ma .kpi{padding:11px 13px;border-right:1px solid var(--b)}.ma .kpi:last-child{border:0}.ma .kpi-label{color:#7b8799;font-size:8.5px;font-weight:750;text-transform:uppercase;letter-spacing:.045em}.ma .kpi-value{margin-top:4px;color:var(--t);font-size:17px;font-weight:750}.ma .kpi.danger .kpi-value{color:#b42318}.ma .grid-2{display:grid;grid-template-columns:1.25fr .75fr;gap:12px}.ma table{margin:0;font-size:11.5px}.ma table thead th{padding:8px 10px;color:#667085;background:#f8fafc;border-bottom:1px solid var(--b);font-size:9px;text-transform:uppercase;letter-spacing:.045em;white-space:nowrap}.ma table tbody td{padding:8px 10px;color:#475467;border-color:#edf0f4;vertical-align:middle}.ma .name{color:#25344d;font-weight:700}.ma .meta{margin-top:2px;color:#8a95a6;font-size:9.5px}.ma .money{font-variant-numeric:tabular-nums;text-align:right;white-space:nowrap}.ma .badge-soft{display:inline-flex;padding:4px 7px;border-radius:12px;font-size:8.5px;font-weight:800;text-transform:uppercase}.ma .badge-open{color:#b54708;background:#fffaeb}.ma .badge-paid{color:#067647;background:#ecfdf3}.ma .badge-draft{color:#475467;background:#f2f4f7}.ma .btn-ma{display:inline-flex;align-items:center;justify-content:center;gap:5px;min-height:34px;padding:6px 11px;border-radius:6px;font-size:11px;font-weight:700}.ma .form-control,.ma .form-select{min-height:37px;border-color:#d7deea;border-radius:6px;font-size:11.5px}.ma label{margin-bottom:5px;color:#52627a;font-size:9.5px;font-weight:750;text-transform:uppercase;letter-spacing:.035em}.ma .field{margin-bottom:12px}.ma .help{display:block;margin-top:4px;color:#8b96a7;font-size:9.5px}.ma .summary-strip{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--b);border-radius:8px;background:#fff;overflow:hidden;margin-bottom:12px}.ma .summary-cell{padding:10px 13px;border-right:1px solid var(--b)}.ma .summary-cell:last-child{border:0}.ma .summary-cell span{display:block;color:#7a8799;font-size:9px;text-transform:uppercase;font-weight:700}.ma .summary-cell strong{display:block;margin-top:3px;color:var(--t);font-size:16px}.ma .empty{padding:28px!important;text-align:center;color:#8a95a6}.ma .alert ul{margin:0}@media(max-width:1200px){.ma .kpis{grid-template-columns:repeat(3,1fr)}.ma .kpi:nth-child(3){border-right:0}.ma .kpi:nth-child(-n+3){border-bottom:1px solid var(--b)}}@media(max-width:800px){.ma .ma-head{align-items:flex-start;flex-direction:column}.ma .kpis,.ma .summary-strip{grid-template-columns:repeat(2,1fr)}.ma .grid-2{grid-template-columns:1fr}}
</style>
